<?php
namespace App\Actions\Rental;
use App\Models\RentalBooking; use App\Models\RentalRate; use App\Models\RentalVehicle; use App\Models\User; use App\Services\AuditLogger; use Carbon\Carbon; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
class CreateRentalBooking
{
    public function __construct(private AuditLogger $audit) {}
    public function execute(RentalVehicle $vehicle,RentalRate $rate,User $user,array $data): RentalBooking { return DB::transaction(function()use($vehicle,$rate,$user,$data){$vehicle=RentalVehicle::lockForUpdate()->findOrFail($vehicle->id);abort_unless($rate->rental_vehicle_id===$vehicle->id,404);$pickup=Carbon::parse($data['pickup_at']);$return=Carbon::parse($data['return_at']);$blocked=$vehicle->availability()->whereBetween('service_date',[$pickup->toDateString(),$return->copy()->subSecond()->toDateString()])->where('status','blocked')->exists();$overlap=$vehicle->bookings()->whereIn('status',['requested','document_review','approved','active'])->where('pickup_at','<',$return)->where('return_at','>',$pickup)->exists();if($blocked||$overlap)throw ValidationException::withMessages(['pickup_at'=>'Kendaraan tidak tersedia pada periode tersebut.']);if($data['drive_mode']==='self_drive'&&!$vehicle->self_drive_available||$data['drive_mode']==='with_driver'&&!$vehicle->driver_available)throw ValidationException::withMessages(['drive_mode'=>'Mode rental tidak tersedia.']);$days=max(1,$pickup->copy()->startOfDay()->diffInDays($return->copy()->startOfDay()));$unit=(float)$rate->offer->price;$booking=RentalBooking::create($data+['booking_number'=>'RB-'.str()->upper(str()->random(12)),'rental_vehicle_id'=>$vehicle->id,'rental_rate_id'=>$rate->id,'mitra_id'=>$vehicle->catalogEntity->mitra_id,'user_id'=>$user->id,'unit_price'=>$unit,'deposit_amount'=>$vehicle->deposit_amount,'total_amount'=>$unit*$days+(float)$vehicle->deposit_amount,'status'=>'requested']);$booking->documents()->sync($data['document_ids']??[]);$this->audit->record('rental.booking_requested',$booking,[],['status'=>'requested'],$user);return $booking;}); }
}
